import json, importlib, glob, os

failures = 0
for path in sorted(glob.glob("examples/*.json")):
    service = os.path.basename(path)[:-5]
    mod = importlib.import_module(f"clients.{service}")
    cases = json.load(open(path))
    for i, case in enumerate(cases):
        record = case["record"]
        original = json.loads(json.dumps(record))
        expected = case["result"]
        try:
            got = mod.normalize(record)
            outcome = {"ok": got}
        except Exception as exc:
            outcome = {"err": type(exc).__name__}
        if outcome != expected:
            failures += 1
            print("FAIL", service, i)
            print("  expected:", expected)
            print("  got     :", outcome)
        if record != original:
            failures += 1
            print("MUTATED INPUT", service, i)
print("failures:", failures)

